    {"ip": "10.30.12.55", "inferred_role": "lateral_movement_target_finance_fileserver", "first_seen": "2028-01-17T02:38:42+0100", "last_seen": "2028-01-17T02:38:42+0100", "agent_name": "FILESVR-FIN-01"}
